using TrophicAnalysis
using Test
using Graphs

@testset "TrophicAnalysis.jl" begin
    # completely coherent
    G1 = DiGraph([0 1 0; 0 0 1; 0 0 0])
    @test trophic_incoherence(G1) == (0.0, [0.0, 1.0, 2.0])

    # 3-cycle
    G2 = DiGraph([0 1 0; 0 0 1; 1 0 0])
    @test trophic_incoherence(G2) == (1.0, [0.0, 0.0, 0.0])

    # complete DiGraph
    G3 = DiGraph([0 1 1; 1 0 1; 1 1 0])
    @test trophic_incoherence(G3) == (1.0, [0.0, 0.0, 0.0])

    # all-but-one edge
    G4 = DiGraph([0 1 1; 1 0 1; 0 1 0])
    @test trophic_incoherence(G4) == (0.9, [0.0, 0.25, 0.5])

    # feed-forward but not completely coherent
    G5 = DiGraph([0 1 1; 0 0 1; 0 0 0])
    @test trophic_incoherence(G5)[1] ≈ 0.11111111111111112
    @test trophic_incoherence(G5)[2] ≈ [0., 0.66666667, 1.33333333]

